/* VNMY — встроенные вселенные и новеллы для открытия с диска (file://).
 * Не правим руками: npm run build
 */
window.__VNMY_BUILTIN_LIBRARY__ = {"schema":2,"universes":[{"schema":1,"id":"tihaya","title":"Тихая","author":"Fobeza","description":"Земля Франца-Иосифа, полярная ночь и одна станция на скале. Шесть человек, четыре месяца до рассвета и связи ровно десять минут в сутки.","cover":"novels/ice-shift/assets/bg-station.webp","accent":"#8fb8d8","order":1,"baseUrl":"","novels":[{"schema":1,"id":"story_ice_shift","title":"Ледовая смена · Акты I–II","author":"Fobeza","description":"Полярная станция «Тихая», шесть человек и пять суток без связи. Первые два акта: знакомство, первый сбой и ночь, когда станция сама позвала на помощь.","cover":"assets/bg-antenna.webp","accent":"#8fb8d8","universe":"tihaya","lang":"ru","vars":[{"name":"имя","type":"text","initial":"Артём"},{"name":"route","type":"text","initial":""},{"name":"trust_vera","type":"number","initial":0},{"name":"trust_alya","type":"number","initial":0},{"name":"trust_kim","type":"number","initial":0},{"name":"trust_dan","type":"number","initial":0},{"name":"trust_grisha","type":"number","initial":0},{"name":"evidence","type":"number","initial":0},{"name":"heat","type":"number","initial":3},{"name":"meds","type":"number","initial":2},{"name":"comms","type":"bool","initial":false},{"name":"journal_read","type":"bool","initial":false},{"name":"asked_kim","type":"bool","initial":false},{"name":"saw_light","type":"bool","initial":false},{"name":"woke_kim","type":"bool","initial":false},{"name":"scalpel","type":"bool","initial":false},{"name":"told_vera","type":"bool","initial":false},{"name":"beacon","type":"bool","initial":false}],"characters":[{"id":"hero","name":"{имя}","color":"#f0d1a1","sprites":{}},{"id":"kim","name":"Ким","color":"#a8b8c8","sprites":{"neutral":"assets/kim-neutral.webp","hard":"assets/kim-hard.webp"}},{"id":"vera","name":"Вера","color":"#d98a5a","sprites":{"neutral":"assets/vera-neutral.webp","soft":"assets/vera-soft.webp"}},{"id":"alya","name":"Аля","color":"#9ec7d8","sprites":{"neutral":"assets/alya-neutral.webp","scared":"assets/alya-scared.webp"}},{"id":"grisha","name":"Гриша","color":"#c9a87a","sprites":{"neutral":"assets/grisha-neutral.webp","warm":"assets/grisha-warm.webp"}},{"id":"dan","name":"Дан","color":"#b7a8d8","sprites":{"neutral":"assets/dan-neutral.webp","tense":"assets/dan-tense.webp"}}],"scenes":[{"id":"sc_open","name":"Бухта Тихая · 11:20","act":"Акт I · Первая тишина","bg":"assets/bg-station.webp","weather":"dust","cast":[],"steps":[{"id":"t1","speaker":null,"text":"Ветер идёт с моря и несёт снежную пыль — мелкую, как мука. Она садится на ресницы, на воротник, на стекло фонаря."},{"id":"t2","speaker":null,"text":"Ты стоишь у склада с ящиком консервов и смотришь на дом. Горит одно окно — то, что над медпунктом. Остальные тёмные: экономия, приказ начальника, третья зима без лишнего света."},{"id":"t3","speaker":null,"text":"Три недели назад ты приехал сюда, чтобы не решать ничего, кроме температуры и давления. Пока получается."},{"id":"t4","speaker":null,"text":"В кармане — письмо, написанное в первую ночь. Ты не отправил его и до сих пор не решил, из упрямства или из милосердия."},{"id":"t5","speaker":"hero","text":"— Ладно, — говоришь ты вслух. Ветер забирает слово раньше, чем ты успеваешь его услышать."},{"id":"t6","speaker":null,"text":"До сеанса — сорок минут. В доме пахнет супом и дизелем: значит, все уже там."}]},{"id":"sc_med","name":"Медпункт · 11:41","act":"Акт I · Первая тишина","bg":"assets/bg-med.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"Медпункт пахнет спиртом и старой бумагой. Кушетка застелена, шкаф закрыт, лампа под зелёным абажуром горит с той стороны, где не бывает сквозняка."},{"id":"t2","speaker":null,"text":"Ты садишься за стол и включаешь диктофон. Так положено: врач на зимовке ведёт голосовой журнал, чтобы потом никто не спорил, что было и чего не было."},{"id":"t3","speaker":null,"text":"Ты нажимаешь кнопку и называешь себя — не для записи, а чтобы услышать свой голос в пустой комнате.","ask":{"var":"имя","label":"Назови себя для журнала","placeholder":"Твоё имя","value":"Артём"}},{"id":"t4","speaker":"hero","text":"— Смена. День двадцать второй. Врач {имя}. Жалоб нет. — Ты выключаешь запись и слушаешь, как дизель за стеной держит ритм."},{"id":"t5","speaker":null,"text":"На столе лежит прошлогодний журнал. Толстая тетрадь с разлинованными страницами, на форзаце фамилия: «Одинцов В. С.». Тот, кто был здесь до тебя."},{"id":"t6","speaker":null,"text":"В августе он погиб на льду. Официально — несчастный случай: пошёл один, поскользнулся, ударился головой. Ты читал заключение дважды, потому что тебе показалось, что в нём не хватает одной страницы."},{"id":"t7","speaker":null,"text":"","choices":[{"text":"Открыть журнал на декабре","goto":"sc_med:c_read"},{"text":"Оставить журнал и идти на сеанс","goto":"sc_med:c_skip"}]},{"id":"c_read","speaker":null,"text":"Ты открываешь тетрадь на последней странице.","set":[{"var":"journal_read","op":"set","value":true},{"var":"evidence","op":"add","value":1}],"goto":"sc_med:t8"},{"id":"c_skip","speaker":null,"text":"Ты закрываешь журнал ладонью, как будто он может что-то сказать вслух.","goto":"sc_med:t8"},{"id":"t8","speaker":null,"text":"За стеной дизель делает вдох и на секунду замолкает. Потом снова: ровно, как сердце, которое не спрашивают, хочет ли оно работать."},{"id":"t9","speaker":null,"text":"На последней странице — 14 декабря. Строка обрывается на середине, и дальше бумага вычищена лезвием: волокна взъерошены, чернила остались только в углублениях.","if":"journal_read"}]},{"id":"sc_radio","name":"Радиорубка · 11:57","act":"Акт I · Первая тишина","bg":"assets/bg-radio.webp","weather":"none","cast":[{"char":"alya","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"В радиорубке тесно, как в шкафу. Аля сидит, поджав ноги, и крутит верньер, хотя крутить уже нечего: терминал цифровой, верньер здесь для привычки."},{"id":"t2","speaker":"alya","text":"— Одиннадцать пятьдесят восемь. Сейчас поймаем."},{"id":"t3","speaker":null,"text":"Она говорит это каждый день. И каждый день в двенадцать в динамике щёлкает, а потом наступает ровная, аккуратная тишина."},{"id":"t4","speaker":null,"text":"В 12:00 щёлкает. В 12:03 — снова. В 12:10 Аля снимает наушники и кладёт их на стол так осторожно, будто они могут разбиться."},{"id":"t5","speaker":"alya","text":"— Спутник ушёл. Или у нас. — Она не смотрит на тебя. — Или у нас.","spriteOverride":"scared"},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Спросить, что она слышит в тишине","goto":"sc_radio:c_ask"},{"text":"Налить ей чай и промолчать","goto":"sc_radio:c_tea"}]},{"id":"c_ask","speaker":null,"text":"— В тишине? — Аля думает так долго, что ты успеваешь пожалеть о вопросе. — Как будто кто-то не нажал кнопку. Стоит рядом и не нажимает.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_radio:t7"},{"id":"c_tea","speaker":null,"text":"Ты наливаешь ей чай, не спрашивая. Она обхватывает кружку обеими руками и держит, пока не становится больно.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_radio:t7"},{"id":"t7","speaker":null,"text":"Дверь открывается без стука. Ким — в свитере, с фонарём на поясе. Лицо спокойное, как у человека, который давно решил, что паника — это роскошь.","cast":[{"char":"alya","sprite":"neutral","pos":"left"},{"char":"kim","sprite":"neutral","pos":"right"}]},{"id":"t8","speaker":"kim","text":"— Ветер. Антенну занесло. Завтра к утру почистим. — Он смотрит на Алю. — В эфир — только через меня. Без самодеятельности."},{"id":"t9","speaker":null,"text":"Ты замечаешь, что он не спрашивает, что случилось. Он уже знает."},{"id":"t10","speaker":null,"text":"","choices":[{"text":"Спросить, почему нельзя попробовать резерв","goto":"sc_radio:c_reserve"},{"text":"Согласиться и выйти","goto":"sc_radio:c_agree"}]},{"id":"c_reserve","speaker":null,"text":"— У нас есть резервный передатчик, — говоришь ты. — Почему не он?","set":[{"var":"asked_kim","op":"set","value":true}],"goto":"sc_radio:t11"},{"id":"c_agree","speaker":null,"text":"Ты киваешь. Киму не нужно большего: он уже поворачивается к двери.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_radio:t12"},{"id":"t11","speaker":"kim","text":"— Потому что резерв — это вышка. А вышка в такой ветер — это двадцать минут на улице и один дурак на растяжках. — Он выдерживает паузу. — У нас нет лишних дураков."},{"id":"t12","speaker":null,"text":"Он уходит, и дверь за ним закрывается мягко, без стука. Аля смотрит на неё ещё секунды три."}]},{"id":"sc_hall","name":"Кают-компания · 13:10","act":"Акт I · Первая тишина","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"grisha","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"К обеду в кают-компании пахнет супом и мокрой шерстью. На столе шесть кружек, но садятся пятеро: Аля осталась в радиорубке."},{"id":"t2","speaker":"grisha","text":"— Кто не ест, тот мёрзнет, — объявляет Гриша и ставит перед тобой тарелку. — Ешь, доктор. Ты у нас один."},{"id":"t3","speaker":null,"text":"Ким ест быстро и аккуратно, будто прибирает за собой. Дан смотрит в тарелку и не поднимает глаз. Гриша режет хлеб и делает вид, что не наблюдает за всеми сразу."},{"id":"t4","speaker":"kim","text":"— Сеанса не было. Завтра будет. — Он не повышает голос. — Антенна, ветер, регламент. Всё."},{"id":"t5","speaker":null,"text":"Дверь хлопает. Вера входит, не снимая куртки, и садится на край стола — там, где не принято.","cast":[{"char":"kim","sprite":"neutral","pos":"right"},{"char":"vera","sprite":"neutral","pos":"left"}]},{"id":"t6","speaker":"vera","text":"— Дизель стучит. — Она говорит это Киму, но смотрит на тебя. — Третий день. Если стукнет сильнее, дом остынет за ночь."},{"id":"t7","speaker":"kim","text":"— Значит, починишь."},{"id":"t8","speaker":"vera","text":"— Значит, дам тебе список того, чего у нас нет. — Она наконец садится. — Начну с прокладки."},{"id":"t9","speaker":null,"text":"","choices":[{"text":"Спросить Веру, что нужно для ремонта","goto":"sc_hall:c_vera"},{"text":"Спросить Дана, как в этом году лёд","goto":"sc_hall:c_dan"},{"text":"Молчать и смотреть, кто как реагирует","goto":"sc_hall:c_watch"}]},{"id":"c_vera","speaker":null,"text":"— Прокладка, — повторяет Вера. — И человек, который подержит лампу. — Она смотрит на тебя ровно столько, сколько нужно, чтобы это стало приглашением.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_hall:t10"},{"id":"c_dan","speaker":null,"text":"— Лёд как лёд, — отвечает Дан, не поднимая глаз. — В этом году толще. — Он говорит это слишком быстро и сам это слышит.","set":[{"var":"trust_dan","op":"add","value":1}],"goto":"sc_hall:t10"},{"id":"c_watch","speaker":null,"text":"Ты молчишь и ешь. Гриша перестаёт резать хлеб. Ким смотрит на часы, хотя часы висят у него за спиной.","goto":"sc_hall:t10"},{"id":"t10","speaker":null,"text":"Ты запоминаешь это, потому что не знаешь, зачем. Пока."}]},{"id":"sc_diesel","name":"Дизельная · 14:20","act":"Акт I · Первая тишина","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"В дизельной жарко и громко. Вера стоит по колено в железном грохоте, с фонарём в зубах и ключом в руке."},{"id":"t2","speaker":null,"text":"Ты держишь лампу. Она показывает, куда светить, коротким кивком — как будто вы работаете вместе не первый год."},{"id":"t3","speaker":"vera","text":"— Держи ровно. Не тряси. — Пауза. — Ты вообще раньше с дизелем дело имел?"},{"id":"t4","speaker":"hero","text":"— С людьми. С дизелем — нет."},{"id":"t5","speaker":"vera","text":"— Люди сложнее. — Она вытирает руки о комбинезон. — Ладно. Проще."},{"id":"t6","speaker":null,"text":"Она подкручивает что-то, и стук на секунду становится ровнее. На секунду."},{"id":"t7","speaker":"vera","text":"— Ты знал, что до тебя здесь был другой врач?"},{"id":"t8","speaker":null,"text":"","choices":[{"text":"Сказать: только то, что в отчёте","goto":"sc_diesel:c_report"},{"text":"Сказать: он погиб на льду год назад","goto":"sc_diesel:c_death"},{"text":"Спросить, почему она спрашивает","goto":"sc_diesel:c_why"}]},{"id":"c_report","speaker":null,"text":"— Только то, что в отчёте, — говоришь ты. Она кивает так, будто ты подтвердил что-то важное.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_diesel:t9"},{"id":"c_death","speaker":null,"text":"— Он погиб на льду. Год назад. — Ты говоришь это нейтрально, как диагноз.","goto":"sc_diesel:t9"},{"id":"c_why","speaker":null,"text":"— А почему ты спрашиваешь? — Вера вытирает руки медленнее, чем нужно.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_diesel:t9"},{"id":"t9","speaker":"vera","text":"— Ясно. — Она закручивает последнюю гайку и выпрямляется. — Значит, отчёт."},{"id":"t10","speaker":null,"text":"На её ладони — свежий порез, узкий, как от бумаги. Она замечает твой взгляд и сжимает руку в кулак."}]},{"id":"sc_med_grisha","name":"Медпункт · 16:05","act":"Акт I · Первая тишина","bg":"assets/bg-med.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"Гриша приходит в пять, с обожжённой ладонью и извинениями."},{"id":"t2","speaker":"grisha","text":"— Плита. Рукав. Сам виноват. — Он улыбается, и от этой улыбки становится только тревожнее.","cast":[{"char":"grisha","sprite":"neutral","pos":"center"}],"spriteOverride":"warm"},{"id":"t3","speaker":null,"text":"Ты обрабатываешь ожог. Он смотрит в сторону — на шкаф, где лежит прошлогодний журнал."},{"id":"t4","speaker":"grisha","text":"— Ты его читаешь? — тихо спрашивает он. — Славин?"},{"id":"t5","speaker":null,"text":"","choices":[{"text":"Спросить, что он видел в ту ночь","goto":"sc_med_grisha:c_ask"},{"text":"Сказать, что читаешь, и не давить","goto":"sc_med_grisha:c_soft"},{"text":"Соврать, что не читаешь","goto":"sc_med_grisha:c_lie"}]},{"id":"c_ask","speaker":null,"text":"— Что ты видел в ту ночь? — Гриша долго молчит, и бинт в твоих руках становится слишком тугим.","set":[{"var":"evidence","op":"add","value":1},{"var":"trust_grisha","op":"add","value":1}],"goto":"sc_med_grisha:t6"},{"id":"c_soft","speaker":null,"text":"— Читаю, — говоришь ты. — Понемногу. — Гриша кивает, и его плечи чуть опускаются.","set":[{"var":"trust_grisha","op":"add","value":1}],"goto":"sc_med_grisha:t6"},{"id":"c_lie","speaker":null,"text":"— Нет, — говоришь ты. — Не читаю. — Он кивает, но с этого момента смотрит только на свою руку.","set":[{"var":"trust_grisha","op":"sub","value":1}],"goto":"sc_med_grisha:t6"},{"id":"t6","speaker":"grisha","text":"— Я в ту ночь плохо спал, — говорит он вместо ответа. — И видел в окно, как кто-то шёл к вышке. Не один."},{"id":"t7","speaker":null,"text":"Он уходит раньше, чем ты успеваешь спросить, что значит «не один». Ты открываешь журнал на последней странице. 14 декабря.","set":[{"var":"evidence","op":"add","value":1}],"cast":[]},{"id":"t8","speaker":null,"text":"Строка обрывается на середине: «...в 23:40 ушёл к вышке. Ким...» Дальше бумага вычищена лезвием."},{"id":"t9","speaker":"hero","text":"— Ким, — читаешь ты вслух. — И дальше — пусто."}]},{"id":"sc_evening","name":"Кают-компания · 19:30","act":"Акт I · Первая тишина","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"},{"char":"vera","sprite":"neutral","pos":"left"}],"steps":[{"id":"t1","speaker":null,"text":"Вечер. Ветер усиливается, и дом начинает отвечать: стекло звенит, труба гудит, где-то на чердаке что-то катается."},{"id":"t2","speaker":null,"text":"Свет мигает дважды. Все поднимают головы — и все опускают, кроме Веры.","mood":"flash"},{"id":"t3","speaker":"vera","text":"— Не я, — говорит она Киму. — Пока не я."},{"id":"t4","speaker":"kim","text":"— Завтра почистим антенну, проверим дизель и ляжем вовремя. — Он гасит верхний свет, оставляя лампу над столом. — Всем ясно?","spriteOverride":"hard"},{"id":"t5","speaker":null,"text":"Ты видишь, как Дан открывает рот, чтобы что-то сказать, и закрывает."},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Спросить при всех, почему нельзя вызвать вертолёт","goto":"sc_evening:c_heli"},{"text":"Спросить Дана, что он хотел сказать","goto":"sc_evening:c_dan"},{"text":"Промолчать","goto":"sc_evening:c_quiet"}]},{"id":"c_heli","speaker":null,"text":"— Почему мы не вызываем вертолёт? — спрашиваешь ты. Кружки на столе останавливаются одновременно.","set":[{"var":"asked_kim","op":"set","value":true},{"var":"trust_kim","op":"sub","value":1}],"goto":"sc_evening:t7"},{"id":"c_dan","speaker":null,"text":"— Дан? — оборачиваешься ты. — Ты что-то хотел сказать.","set":[{"var":"trust_dan","op":"add","value":1}],"goto":"sc_evening:t8"},{"id":"c_quiet","speaker":null,"text":"Ты молчишь. Иногда молчание — это способ услышать больше.","goto":"sc_evening:t9"},{"id":"t7","speaker":"kim","text":"— Вертолёт — это расследование, — говорит он ровно. — А расследование — это конец станции. Ты хочешь остаться здесь до апреля с теми, кого уже допрашивали?"},{"id":"t8","speaker":"dan","text":"— Ничего, — говорит Дан. — Показалось."},{"id":"t9","speaker":null,"text":"Ночью тебе снится больница. Кто-то на соседней койке считает до сорока, и ты просыпаешься на «тридцати семи»."}]},{"id":"sc_night","name":"Каюта · 02:14","act":"Акт I · Первая тишина","bg":"assets/bg-cabin.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"В каюте холодно. Не как на улице — как в пальто, которое забыли просушить."},{"id":"t2","speaker":null,"text":"В трубах щёлкает. Раз. Другой. Ты смотришь на часы: 02:14."},{"id":"t3","speaker":null,"text":"В окне, за стеклом, на склоне — свет. Маленький, ровный. Он движется к антенному полю."},{"id":"t4","speaker":null,"text":"","choices":[{"text":"Одеться и выйти следом","goto":"sc_night:c_follow"},{"text":"Разбудить Кима","goto":"sc_night:c_kim"},{"text":"Спуститься в дизельную","goto":"sc_night:c_diesel"}]},{"id":"c_follow","speaker":null,"text":"Ты натягиваешь куртку поверх свитера и выходишь в коридор, стараясь не скрипеть половицами.","set":[{"var":"saw_light","op":"set","value":true}],"goto":"sc_night:t5"},{"id":"c_kim","speaker":null,"text":"Ты стучишь в дверь Кима. Он открывает сразу, как будто не спал.","set":[{"var":"woke_kim","op":"set","value":true},{"var":"saw_light","op":"set","value":true}],"goto":"sc_night:t5"},{"id":"c_diesel","speaker":null,"text":"Ты идёшь вниз, к дизельной: свет может быть просто лампой, забытой на столе.","goto":"sc_night:t5"},{"id":"t5","speaker":null,"text":"В коридоре пахнет холодом и металлом. Дверь в дизельную приоткрыта, и оттуда идёт свет."},{"id":"t6","speaker":"kim","text":"— Это Вера, — говорит Ким, не открывая глаз. — Тяга. Спи.","if":"woke_kim"},{"id":"t7","speaker":null,"text":"Он не встаёт. Ты стоишь в темноте ещё минуту и всё-таки идёшь вниз.","if":"woke_kim"}]},{"id":"sc_night_diesel","name":"Дизельная · 02:40","act":"Акт I · Первая тишина","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Вера сидит на перевёрнутом ящике, сбросив капюшон. В дизельной тепло, но на её плечах — снег."},{"id":"t2","speaker":"vera","text":"— Тягу проверяла, — говорит она, не здороваясь."},{"id":"t3","speaker":null,"text":"Снег на её плечах тает и капает на пол. К утру здесь будет лёд."},{"id":"t4","speaker":"hero","text":"— На антенном поле был свет, — говоришь ты. — В два часа ночи.","if":"saw_light"},{"id":"t5","speaker":"vera","text":"— Знаю, — отвечает она, не оборачиваясь. — Это был мой фонарь.","if":"saw_light"},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Спросить, что она там делала","goto":"sc_night_diesel:c_what"},{"text":"Спросить про порез на ладони","goto":"sc_night_diesel:c_hand"},{"text":"Молча сесть рядом","goto":"sc_night_diesel:c_sit"}]},{"id":"c_what","speaker":null,"text":"— Смотрела, цела ли растяжка, — говорит Вера. — Не спрашивай больше. Пока.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_night_diesel:t7"},{"id":"c_hand","speaker":null,"text":"— Дай руку, — говоришь ты. Она не сразу, но разжимает кулак. Порез тонкий, ровный и уже начал воспаляться.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_night_diesel:t7"},{"id":"c_sit","speaker":null,"text":"Ты садишься рядом на второй ящик. Она не отодвигается.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_night_diesel:t7"},{"id":"t7","speaker":"vera","text":"— Я не люблю, когда кто-то уходит в темноту один, — говорит она тихо. — Тут это плохо заканчивается.","spriteOverride":"soft"},{"id":"t8","speaker":null,"text":"Она говорит не о тебе. Ты это понимаешь и ничего не спрашиваешь."}]},{"id":"sc_antenna","name":"Антенное поле · 09:20","act":"Акт I · Первая тишина","bg":"assets/bg-antenna.webp","weather":"dust","cast":[{"char":"vera","sprite":"neutral","pos":"left"}],"steps":[{"id":"t1","speaker":null,"text":"Утром ветер падает до четырнадцати — это почти тишина, если у тебя есть с чем сравнивать."},{"id":"t2","speaker":null,"text":"Вы идёте вдвоём: Ким велел осмотреть мачту, но сам остался у рации — «на случай, если всё-таки поймаем»."},{"id":"t3","speaker":null,"text":"Кабель лежит в снегу, как мёртвая змея. Ты берёшь его в руки и сразу понимаешь: он не оборван. Он разрезан."},{"id":"t4","speaker":null,"text":"Срез ровный, одним движением, с двух сторон — чтобы не замкнуло. Так режут не ветром. Так режут ножом, который есть на станции."},{"id":"t5","speaker":"vera","text":"— Ну? — Она стоит в двух шагах и смотрит не на кабель, а на тебя."},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Сказать, что срез внутренний","goto":"sc_antenna:c_say"},{"text":"Спрятать кабель и молчать","goto":"sc_antenna:c_hide"},{"text":"Позвать Кима","goto":"sc_antenna:c_kim"}]},{"id":"c_say","speaker":null,"text":"— Его перерезали, — говоришь ты, глядя ей в глаза. — Изнутри.","set":[{"var":"trust_vera","op":"add","value":1},{"var":"evidence","op":"add","value":1}],"goto":"sc_antenna:t7"},{"id":"c_hide","speaker":null,"text":"Ты заталкиваешь кабель под снег, как будто это может что-то изменить.","set":[{"var":"evidence","op":"add","value":1}],"goto":"sc_antenna:t7"},{"id":"c_kim","speaker":null,"text":"Ты машешь рукой в сторону дома. Ким выходит на крыльцо, и ты показываешь ему срез.","set":[{"var":"trust_kim","op":"add","value":1},{"var":"evidence","op":"add","value":1}],"goto":"sc_antenna:t7"},{"id":"t7","speaker":null,"text":"В снегу рядом — след от колена и обрывок синей изоленты. Такая изолента есть только в дизельной."}]},{"id":"sc_confront","name":"Кают-компания · 10:40","act":"Акт I · Первая тишина","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"},{"char":"vera","sprite":"neutral","pos":"left"}],"steps":[{"id":"t1","speaker":null,"text":"К одиннадцати в кают-компании собираются все. Кабель лежит на столе, между солонкой и картой."},{"id":"t2","speaker":"kim","text":"— Объясни, — говорит он тебе. — Только по факту."},{"id":"t3","speaker":null,"text":"Ты говоришь. Вера молчит. Аля не садится. Гриша держит кружку обеими руками, хотя она давно пустая. Дан смотрит в стену."},{"id":"t4","speaker":"alya","text":"— Значит, это кто-то из нас, — говорит она шёпотом. И от этого шёпота в комнате становится холоднее."},{"id":"t5","speaker":null,"text":"","choices":[{"text":"Сказать вслух: кабель перерезали изнутри","goto":"sc_confront:c_say"},{"text":"Спросить, у кого станционный нож","goto":"sc_confront:c_knife"},{"text":"Согласиться с Кимом: сначала ремонт","goto":"sc_confront:c_wait"}]},{"id":"c_say","speaker":null,"text":"— Его перерезали изнутри, — говоришь ты. Слово «изнутри» остаётся в комнате, как запах.","set":[{"var":"evidence","op":"add","value":1},{"var":"trust_kim","op":"sub","value":1}],"goto":"sc_confront:t6"},{"id":"c_knife","speaker":null,"text":"— У кого станционный нож? — спрашиваешь ты. Тишина становится другой: теперь все смотрят не на тебя, а на стол.","set":[{"var":"evidence","op":"add","value":1}],"goto":"sc_confront:t6"},{"id":"c_wait","speaker":null,"text":"— Сначала ремонт, — соглашаешься ты. Ким кивает, и напряжение в комнате опускается на полтона.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_confront:t6"},{"id":"t6","speaker":"kim","text":"— Ремонт. Сначала ремонт. — Он забирает кабель. — И ещё: с этого часа один из нас всегда на связи. По очереди. Начинаем сегодня.","spriteOverride":"hard"},{"id":"t7","speaker":null,"text":"Он говорит «на связи», но смотрит на тебя. Ты понимаешь, что это не про радио."}]},{"id":"sc_hub","name":"Кают-компания · 11:20","act":"Акт I · Первая тишина","bg":"assets/bg-hall.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"До обеда остаётся час. Час — это единственное, что на станции принадлежит тебе целиком."},{"id":"t2","speaker":null,"text":"Вера уходит в дизельную, не оглядываясь. Аля остаётся у двери радиорубки. Дан идёт в лабораторию и закрывает за собой дверь."},{"id":"t3","speaker":null,"text":"Ты можешь пойти с одним из них. Или ни с кем."},{"id":"t4","speaker":null,"text":"","choices":[{"text":"Пойти с Верой в дизельную","goto":"sc_route_vera:t1"},{"text":"Пойти с Алей в радиорубку","goto":"sc_route_alya:t1"},{"text":"Остаться одному в лаборатории","goto":"sc_route_solo:t1"}]}]},{"id":"sc_route_vera","name":"Дизельная · 11:40","act":"Акт I · Первая тишина","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Вера ждёт тебя у дизеля, как будто вы договорились. Может, и договорились — просто не словами.","set":[{"var":"route","op":"set","value":"vera"}]},{"id":"t2","speaker":"vera","text":"— Ты видел срез. И я видела, что ты его увидел."},{"id":"t3","speaker":null,"text":"Она берёт со стола ключ, потом кладёт обратно. Пальцы у неё дрожат — не от холода."},{"id":"t4","speaker":"vera","text":"— Если я попрошу тебя кое о чём не спрашивать, ты попросишь взамен?"},{"id":"t5","speaker":null,"text":"","choices":[{"text":"Скажи, о чём","goto":"sc_route_vera:c_tell"},{"text":"Нет. Я буду спрашивать","goto":"sc_route_vera:c_no"},{"text":"Молчать","goto":"sc_route_vera:c_silent"}]},{"id":"c_tell","speaker":null,"text":"— Скажи, о чём, — просишь ты. — Я не умею не спрашивать.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_route_vera:t6"},{"id":"c_no","speaker":null,"text":"— Нет, — говоришь ты. — Я буду спрашивать. Иначе зачем я здесь.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_route_vera:t6"},{"id":"c_silent","speaker":null,"text":"Ты молчишь. Она кивает так, будто это тоже ответ.","goto":"sc_route_vera:t6"},{"id":"t6","speaker":"vera","text":"— Ладно. — Она впервые смотрит прямо. — Тогда начну с того, что у меня была причина приехать сюда. И это не дизель."},{"id":"t7","speaker":null,"text":"В кармане у неё что-то тяжёлое. Она не достаёт. Ты не просишь."},{"id":"t8","speaker":null,"text":"За стеной дизель делает вдох — и на полтакта замолкает.","mood":"shake"},{"id":"t9","speaker":null,"text":"Ты успеваешь подумать, что «полтакта» — это ровно столько, сколько нужно, чтобы что-то решить.","goto":"sc_a2_open:t1"}]},{"id":"sc_route_alya","name":"Радиорубка · 11:35","act":"Акт I · Первая тишина","bg":"assets/bg-radio.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"Аля закрывает дверь радиорубки на щеколду — впервые за три недели.","set":[{"var":"route","op":"set","value":"alya"}],"cast":[{"char":"alya","sprite":"neutral","pos":"center"}]},{"id":"t2","speaker":"alya","text":"— У меня есть запись. — Она говорит быстро, будто боится, что не успеет. — Последняя передача Славы. Не через терминал. Через резерв."},{"id":"t3","speaker":null,"text":"Она достаёт из-за панели маленький диктофон, обёрнутый в шерстяной носок. Ставит на стол. Не включает."},{"id":"t4","speaker":"alya","text":"— Если отдам Киму — он её уничтожит. Если не отдам — я буду знать, что слышала."},{"id":"t5","speaker":null,"text":"","choices":[{"text":"Включить сейчас","goto":"sc_route_alya:c_play"},{"text":"Спросить, почему она молчала год","goto":"sc_route_alya:c_why"},{"text":"Ничего не трогать","goto":"sc_route_alya:c_stop"}]},{"id":"c_play","speaker":null,"text":"Ты нажимаешь кнопку. Динамик шипит, потом в шипении появляется голос — незнакомый, усталый.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_route_alya:t6"},{"id":"c_why","speaker":null,"text":"— Почему ты молчала год? — Аля смотрит на свои руки. — Потому что если бы я отдала запись, меня бы спросили, почему я слушала. А я слушала.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_route_alya:t6"},{"id":"c_stop","speaker":null,"text":"Ты не трогаешь диктофон. Он лежит между вами, как ещё один человек в комнате.","goto":"sc_route_alya:t6"},{"id":"t6","speaker":"alya","text":"— Там три секунды, — говорит она. — И на них он говорит: «...не верь отчёту».","spriteOverride":"scared"},{"id":"t7","speaker":null,"text":"В коридоре шаги. Кто-то останавливается у двери и стоит. Вы оба смотрите на щеколду."},{"id":"t8","speaker":null,"text":"Шаги уходят. Аля выдыхает и кладёт ладонь на диктофон, как будто он может согреться.","goto":"sc_a2_open:t1"}]},{"id":"sc_route_solo","name":"Лаборатория · 11:35","act":"Акт I · Первая тишина","bg":"assets/bg-lab.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"В лаборатории холоднее, чем в доме: тут никто не топит. Ты включаешь лампу над столом Дана.","set":[{"var":"route","op":"set","value":"solo"}]},{"id":"t2","speaker":null,"text":"Полевой журнал лежит открытым. Ты листаешь: цифры, даты, подписи. А потом видишь, что под графитом остались вдавленные следы."},{"id":"t3","speaker":null,"text":"Дан писал карандашом, стирал и обводил ручкой. Один и тот же лёд, две разные толщины. Вторая — на четверть метра больше."},{"id":"t4","speaker":null,"text":"За спиной скрипит дверь. Дан стоит в проёме с чашкой в руке и смотрит на раскрытый журнал.","cast":[{"char":"dan","sprite":"neutral","pos":"center"}]},{"id":"t5","speaker":"dan","text":"— Ты же врач, — говорит он наконец. — Ты же понимаешь, что бывает, когда человеку некуда деваться.","spriteOverride":"tense"},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Сказать: понимаю","goto":"sc_route_solo:c_yes"},{"text":"Спросить, кто заставил","goto":"sc_route_solo:c_who"},{"text":"Сказать: это не оправдание","goto":"sc_route_solo:c_no"}]},{"id":"c_yes","speaker":null,"text":"— Понимаю, — говоришь ты. И это правда, которая тебе самому не нравится.","set":[{"var":"trust_dan","op":"add","value":1}],"goto":"sc_route_solo:t7"},{"id":"c_who","speaker":null,"text":"— Кто заставил? — Дан ставит чашку так, что она стучит о блюдце. — Никто. Все. Институт. Я сам.","set":[{"var":"evidence","op":"add","value":1},{"var":"trust_dan","op":"add","value":1}],"goto":"sc_route_solo:t7"},{"id":"c_no","speaker":null,"text":"— Это не оправдание, — говоришь ты. Дан кивает. — Нет. Не оправдание.","goto":"sc_route_solo:t7"},{"id":"t7","speaker":null,"text":"Он садится на табурет, ставит чашку и не пьёт. За окном начинается ветер — сначала тихо, будто кто-то пробует голос."},{"id":"t8","speaker":null,"text":"На столе между вами лежит журнал. Один и тот же лёд. Две разные толщины. Ты ещё не знаешь, какая из них настоящая.","goto":"sc_a2_open:t1"}]},{"id":"sc_a2_open","name":"Кают-компания · 08:10","act":"Акт II · Сквозняк","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"},{"char":"vera","sprite":"neutral","pos":"left"}],"steps":[{"id":"t1","speaker":null,"text":"Утром в кают-компании холоднее, чем вчера. Стёкла изнутри затянуло изморозью — значит, тепло уходит быстрее, чем дизель успевает его давать.","set":[{"var":"heat","op":"sub","value":1}]},{"id":"t2","speaker":null,"text":"Ким собирает всех после завтрака. Перед ним на столе — раскрытая сумка с инструментом и пустая тряпица."},{"id":"t3","speaker":"kim","text":"— Сдаём всё, что режет. Ножи, лезвия, отвёртки с заточкой. Каждый кладёт и называет. — Он не смотрит ни на кого. — Это не обвинение. Это инвентаризация.","spriteOverride":"hard"},{"id":"t4","speaker":null,"text":"Гриша кладёт кухонный нож. Аля — маникюрные ножницы. Дан — перочинный. Вера — складной нож, не глядя, как будто отдаёт чужое."},{"id":"t5","speaker":null,"text":"Ким смотрит на тебя. В медпункте лежит скальпель — единственный предмет, который он не назвал."},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Сдать скальпель","goto":"sc_a2_open:c_give"},{"text":"Оставить скальпель и промолчать","goto":"sc_a2_open:c_keep"},{"text":"Сказать, что он нужен для работы","goto":"sc_a2_open:c_tell"}]},{"id":"c_give","speaker":null,"text":"Ты приносишь скальпель и кладёшь его на тряпицу. Ким кивает так, будто ты сдал экзамен, который никто не объявлял.","set":[{"var":"scalpel","op":"set","value":false},{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_open:t7"},{"id":"c_keep","speaker":null,"text":"Ты не двигаешься. Ким выдерживает паузу и говорит: «После обеда сам принесёшь». Ты киваешь — и знаешь, что не принесёшь.","set":[{"var":"scalpel","op":"set","value":true}],"goto":"sc_a2_open:t7"},{"id":"c_tell","speaker":null,"text":"— Он нужен для работы, — говоришь ты. — Но лежит в шкафу, можешь проверить. — Ким смотрит на тебя дольше, чем нужно.","set":[{"var":"scalpel","op":"set","value":true},{"var":"trust_kim","op":"sub","value":1}],"goto":"sc_a2_open:t7"},{"id":"t7","speaker":"kim","text":"— К вечеру будет шторм. После обеда закроем выход. — Он застёгивает сумку. — И ещё: если кто-то что-то знает — сейчас самое время."},{"id":"t8","speaker":null,"text":"Никто не говорит. Ты слышишь, как в стене щёлкает труба, и понимаешь, что до вечера осталось меньше, чем кажется."},{"id":"t9","speaker":null,"text":"Ты выходишь в коридор. Дом гудит ровно, как будто ещё ничего не случилось.","gotoIf":[{"when":"route == \"vera\"","goto":"sc_a2_vera_1:t1"},{"when":"route == \"alya\"","goto":"sc_a2_alya_1:t1"},{"when":"route == \"solo\"","goto":"sc_a2_solo_1:t1"}]}]},{"id":"sc_a2_vera_1","name":"Дизельная · 09:05","act":"Акт II · Сквозняк","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Вера ждёт тебя в дизельной с фонарём, который не включает. Свет идёт только от лампы над верстаком."},{"id":"t2","speaker":"vera","text":"— Я хотела сказать это раньше. — Она садится на ящик. — Одинцов — моя фамилия. Вера Одинцова. Слава был моим братом.","spriteOverride":"soft"},{"id":"t3","speaker":null,"text":"Она говорит это ровно, как человек, который репетировал фразу всю зиму и всё равно не нашёл нужной интонации."},{"id":"t4","speaker":null,"text":"","choices":[{"text":"«Я так и понял»","goto":"sc_a2_vera_1:c_knew"},{"text":"«Почему ты молчала?»","goto":"sc_a2_vera_1:c_why"},{"text":"«Мне жаль»","goto":"sc_a2_vera_1:c_sorry"}]},{"id":"c_knew","speaker":null,"text":"— Я так и понял, — говоришь ты. — Когда ты спросила про отчёт.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_a2_vera_1:t5"},{"id":"c_why","speaker":null,"text":"— Почему ты молчала? — Вера пожимает плечами. — Потому что здесь все знают его как врача, а меня — как дизелиста. Мне нужно было, чтобы ты сначала увидел меня.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_a2_vera_1:t5"},{"id":"c_sorry","speaker":null,"text":"— Мне жаль, — говоришь ты. Она поднимает глаза, и в них нет благодарности. — Не надо. Жалость тут не работает. Работает правда.","goto":"sc_a2_vera_1:t5"},{"id":"t5","speaker":"vera","text":"— Я приехала не за деньгами и не за могилой. Я приехала узнать, почему его отчёт остался в столе, а не ушёл в институт."},{"id":"t6","speaker":null,"text":"За стеной дизель делает вдох — и на этот раз не выдыхает сразу. Вера встаёт, и разговор заканчивается раньше, чем ты успеваешь задать второй вопрос."}]},{"id":"sc_a2_vera_2","name":"Дизельная · 09:40","act":"Акт II · Сквозняк","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Вы вскрываете кожух. Внутри не поломка, а износ: трещина в прокладке, которую здесь нечем заменить."},{"id":"t2","speaker":"vera","text":"— До утра дотянем. До месяца — нет."},{"id":"t3","speaker":null,"text":"Она вытирает руки и говорит, не поднимая глаз:"},{"id":"t4","speaker":"vera","text":"— Кабель перерезала я. Своим ножом, вчера ночью. Хотела, чтобы пришёл вертолёт и вместе с ним — люди, которые умеют задавать вопросы.","spriteOverride":"soft","if":"trust_vera \u003e= 3"},{"id":"t5","speaker":"vera","text":"— Есть вещи, которые я тебе пока не скажу. Не потому, что не доверяю. Потому что ты ещё не решил, на чьей ты стороне.","if":"trust_vera \u003c 3"},{"id":"t6","speaker":null,"text":"Ты понимаешь, что только что услышал признание или отказ — и в обоих случаях это одно и то же."},{"id":"t7","speaker":null,"text":"На столе лежит её нож. Лезвие чистое, но у основания рукояти забилась синяя изолента, которую она срезала с кабеля.","set":[{"var":"evidence","op":"add","value":1}]},{"id":"t8","speaker":null,"text":"Ты смотришь на её руки. Они не дрожат. Это почему-то страшнее, чем если бы дрожали."}]},{"id":"sc_a2_vera_3","name":"Дизельная · 10:20","act":"Акт II · Сквозняк","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Вы сидите на ящиках, пока дизель держит температуру. Вера спрашивает неожиданно:"},{"id":"t2","speaker":"vera","text":"— Ты почему здесь? Только не говори, что из-за денег.","spriteOverride":"soft"},{"id":"t3","speaker":null,"text":"","choices":[{"text":"Рассказать про пациента","goto":"sc_a2_vera_3:c_tell"},{"text":"Соврать","goto":"sc_a2_vera_3:c_lie"}]},{"id":"c_tell","speaker":null,"text":"— У меня был пациент, — говоришь ты. — Мужчина, сорок один. Умер на столе. До сих пор не знаю, была ли это моя ошибка.","set":[{"var":"told_vera","op":"set","value":true},{"var":"trust_vera","op":"add","value":1}],"goto":"sc_a2_vera_3:t4"},{"id":"c_lie","speaker":null,"text":"— Из-за денег, — говоришь ты. Вера кивает, и ты видишь, что она не поверила ни одному слову.","goto":"sc_a2_vera_3:t4"},{"id":"t4","speaker":"vera","text":"— Значит, ты тоже сюда сбежал. — Она не улыбается. — Ладно. Тут не убежишь, тут холодно."},{"id":"t5","speaker":null,"text":"Она накрывает твою руку своей — коротко, как будто проверяет, тёплая ли. Потом убирает.","if":"told_vera"},{"id":"t6","speaker":null,"text":"Сверху, из дома, доносится приглушённый удар. Что-то тяжёлое упало на крышу — или на антенну.","goto":"sc_a2_storm:t1"}]},{"id":"sc_a2_alya_1","name":"Радиорубка · 09:10","act":"Акт II · Сквозняк","bg":"assets/bg-radio.webp","weather":"none","cast":[{"char":"alya","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Аля ждёт тебя с диктофоном в руках. На этот раз она не прячет его в носок."},{"id":"t2","speaker":"alya","text":"— Я решила. Слушай."},{"id":"t3","speaker":null,"text":"Она нажимает кнопку. Шипение, потом голос — усталый, взрослый, не похожий на голос человека, которому осталось меньше года."},{"id":"t4","speaker":null,"text":"«...проверка связи. Ким, если ты это слышишь — я не буду молчать. Я не верю отчёту за третий квартал. Лёд у третьего створа...»"},{"id":"t5","speaker":null,"text":"Запись обрывается на середине слова. Аля смотрит на диктофон, как на что-то живое.","set":[{"var":"evidence","op":"add","value":1}]},{"id":"t6","speaker":null,"text":"","choices":[{"text":"Спросить, что такое третий створ","goto":"sc_a2_alya_1:c_what"},{"text":"Сказать, что запись надо отдать Киму","goto":"sc_a2_alya_1:c_kim"},{"text":"Промолчать и послушать ещё раз","goto":"sc_a2_alya_1:c_again"}]},{"id":"c_what","speaker":null,"text":"— Третий створ — это там, где Дан мерил лёд, — говорит Аля. — Там, где собирались строить пристань.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_a2_alya_1:t7"},{"id":"c_kim","speaker":null,"text":"— Это надо отдать Киму, — говоришь ты. Аля забирает диктофон и держит его у груди. — Тогда он уничтожит её при тебе. Это будет честнее?","set":[{"var":"trust_alya","op":"sub","value":1}],"goto":"sc_a2_alya_1:t7"},{"id":"c_again","speaker":null,"text":"Ты молчишь. Аля включает запись ещё раз, и вы слушаете одни и те же три секунды, пока они не перестают быть словами.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_a2_alya_1:t7"},{"id":"t7","speaker":null,"text":"В дверь стучат. Три раза, ровно, как стучат люди, которые не сомневаются, что им откроют."}]},{"id":"sc_a2_alya_2","name":"Радиорубка · 09:20","act":"Акт II · Сквозняк","bg":"assets/bg-radio.webp","weather":"none","cast":[{"char":"alya","sprite":"scared","pos":"center"}],"steps":[{"id":"t1","speaker":"alya","text":"— Это Ким. — Она смотрит на тебя. — Если он найдёт запись, он её не просто уничтожит.","spriteOverride":"scared"},{"id":"t2","speaker":null,"text":"","choices":[{"text":"Спрятать диктофон и открыть","goto":"sc_a2_alya_2:c_hide"},{"text":"Открыть и сказать правду","goto":"sc_a2_alya_2:c_truth"},{"text":"Не открывать","goto":"sc_a2_alya_2:c_locked"}]},{"id":"c_hide","speaker":null,"text":"Ты заталкиваешь диктофон за панель, а Аля отпирает дверь. Ким заходит, смотрит на терминал и не спрашивает ничего лишнего.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_a2_alya_2:t3"},{"id":"c_truth","speaker":null,"text":"Ты открываешь дверь и говоришь, что у Али есть запись. Ким молчит так долго, что становится слышно, как гудит дизель.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_alya_2:t3"},{"id":"c_locked","speaker":null,"text":"Ты не открываешь. Шаги за дверью стоят, потом уходят. Аля выдыхает, но не выглядит благодарной.","set":[{"var":"trust_alya","op":"add","value":1},{"var":"trust_kim","op":"sub","value":1}],"goto":"sc_a2_alya_2:t3"},{"id":"t3","speaker":null,"text":"Ким не заходит дальше порога. Он говорит через дверь, ровно и негромко:"},{"id":"t4","speaker":"kim","text":"— {имя}. Выйди. Разговор есть."},{"id":"t5","speaker":null,"text":"Аля задерживает дыхание. Ты выходишь в коридор.","goto":"sc_a2_alya_3:t1"}]},{"id":"sc_a2_alya_3","name":"Коридор · 09:25","act":"Акт II · Сквозняк","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"}],"steps":[{"id":"t1","speaker":null,"text":"Ким стоит у окна, за которым ничего нет, кроме чёрного стекла и отражения лампы."},{"id":"t2","speaker":"kim","text":"— Ты много ходишь. — Он не оборачивается. — Я не против. Мне нужно, чтобы кто-то видел то же, что и я."},{"id":"t3","speaker":"kim","text":"— Скажи мне одну вещь. Если бы ты знал, что человек погиб из-за чужого молчания, — ты бы сказал об этом вслух?"},{"id":"t4","speaker":null,"text":"","choices":[{"text":"«Сказал бы»","goto":"sc_a2_alya_3:c_yes"},{"text":"«Сначала выслушал бы»","goto":"sc_a2_alya_3:c_listen"},{"text":"«Не знаю»","goto":"sc_a2_alya_3:c_dunno"}]},{"id":"c_yes","speaker":null,"text":"— Сказал бы, — отвечаешь ты. Ким кивает, и в этом кивке нет ни согласия, ни осуждения.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_alya_3:t5"},{"id":"c_listen","speaker":null,"text":"— Сначала выслушал бы, — говоришь ты. — Потом сказал.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_alya_3:t5"},{"id":"c_dunno","speaker":null,"text":"— Не знаю, — честно говоришь ты. Ким впервые поворачивается к тебе. — Спасибо. Это единственный честный ответ за сегодня.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_alya_3:t5"},{"id":"t5","speaker":"kim","text":"— Вот и я не знаю. — Он говорит это тихо, и впервые за всё время ты видишь, что он старый."},{"id":"t6","speaker":null,"text":"Сверху доносится удар. Дом вздрагивает, и лампа под потолком качается, будто её толкнули рукой.","goto":"sc_a2_storm:t1"}]},{"id":"sc_a2_solo_1","name":"Лаборатория · 09:15","act":"Акт II · Сквозняк","bg":"assets/bg-lab.webp","weather":"none","cast":[{"char":"dan","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"В лаборатории Дан сидит перед двумя журналами. Один — полевой, в клеёнчатой обложке. Второй — тот, что уйдёт в институт."},{"id":"t2","speaker":"dan","text":"— Ты уже видел. — Он не оборачивается. — Спрашивай."},{"id":"t3","speaker":null,"text":"","choices":[{"text":"«Какая колонка настоящая?»","goto":"sc_a2_solo_1:c_real"},{"text":"«Кто тебя заставил?»","goto":"sc_a2_solo_1:c_who"},{"text":"«Зачем ты это сделал?»","goto":"sc_a2_solo_1:c_why"}]},{"id":"c_real","speaker":null,"text":"— Настоящая — та, что карандашом, — говорит Дан. — Лёд тоньше на четверть метра. Если это уйдёт в институт, пристань не построят. И станцию закроют.","set":[{"var":"evidence","op":"add","value":1},{"var":"trust_dan","op":"add","value":1}],"goto":"sc_a2_solo_1:t4"},{"id":"c_who","speaker":null,"text":"— Никто, — говорит Дан. — Институту нужны цифры, которые позволят строить. Я тот, кто их пишет. — Он снимает очки и трёт глаза. — Это и есть «никто».","set":[{"var":"evidence","op":"add","value":1},{"var":"trust_dan","op":"add","value":1}],"goto":"sc_a2_solo_1:t4"},{"id":"c_why","speaker":null,"text":"— Потому что я испугался, — говорит Дан. — Не закрытия. Того, что скажут: три года работы, и всё зря. — Он смотрит на журнал. — Теперь скажут другое.","set":[{"var":"evidence","op":"add","value":1}],"goto":"sc_a2_solo_1:t4"},{"id":"t4","speaker":"dan","text":"— Если построят по бумаге, причал уйдёт под воду вместе с пристанью. Через три года. Может, через пять."},{"id":"t5","speaker":null,"text":"Он говорит это без пафоса, как человек, который давно пересчитал всё и не нашёл варианта, где он остаётся хорошим."},{"id":"t6","speaker":null,"text":"За окном начинает подниматься ветер. Стекло в раме отвечает тонким, злым звоном.","goto":"sc_a2_solo_2:t1"}]},{"id":"sc_a2_solo_2","name":"Лаборатория · 09:40","act":"Акт II · Сквозняк","bg":"assets/bg-lab.webp","weather":"none","cast":[{"char":"dan","sprite":"tense","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Дан достаёт из ящика папку и кладёт её перед тобой. Внутри — полевые листы с подписями и датами."},{"id":"t2","speaker":"dan","text":"— Здесь оригиналы. Я собирался сжечь их в печке. — Он смотрит на тебя. — Решай."},{"id":"t3","speaker":null,"text":"","choices":[{"text":"Забрать оригиналы себе","goto":"sc_a2_solo_2:c_take"},{"text":"Сказать, чтобы отдал Киму","goto":"sc_a2_solo_2:c_kim"},{"text":"Сжечь вместе","goto":"sc_a2_solo_2:c_burn"}]},{"id":"c_take","speaker":null,"text":"Ты забираешь папку и убираешь её под свитер. Дан выдыхает так, будто с него сняли вес.","set":[{"var":"evidence","op":"add","value":1}],"goto":"sc_a2_solo_2:t4"},{"id":"c_kim","speaker":null,"text":"— Отдай Киму, — говоришь ты. Дан смотрит на папку, потом на тебя. — Он не обрадуется. Но это его станция.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_solo_2:t4"},{"id":"c_burn","speaker":null,"text":"Вы сжигаете листы в печке по одному. Бумага горит быстро, и запах остаётся в лаборатории до вечера.","set":[{"var":"evidence","op":"sub","value":1},{"var":"trust_dan","op":"add","value":1}],"goto":"sc_a2_solo_2:t4"},{"id":"t4","speaker":"dan","text":"— Спасибо, — говорит он, хотя ты не знаешь, за что именно."},{"id":"t5","speaker":null,"text":"Он уходит первым. Ты остаёшься в лаборатории один."}]},{"id":"sc_a2_solo_3","name":"Лаборатория · 10:05","act":"Акт II · Сквозняк","bg":"assets/bg-lab.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"Второй стол в лаборатории стоит не совсем пустым: в нижнем ящике лежит то, что не поместилось в прошлогодний журнал."},{"id":"t2","speaker":null,"text":"Тетрадь в клетку, без фамилии. На форзаце — одна фраза почерком Славы: «Если со мной что-то случится — сказать Вере, а не Киму».","set":[{"var":"evidence","op":"add","value":1}]},{"id":"t3","speaker":null,"text":"Внутри — расчёты. Лёд, створ, пристань, даты. И на последней странице: «К. знает. Просил подождать до весны»."},{"id":"t4","speaker":"hero","text":"— До весны, — повторяешь ты вслух. В пустой лаборатории это звучит как обвинение."},{"id":"t5","speaker":null,"text":"Ты закрываешь тетрадь и убираешь её во внутренний карман. Над крышей что-то тяжело падает — и весь дом вздрагивает.","goto":"sc_a2_storm:t1"}]},{"id":"sc_a2_storm","name":"Кают-компания · 16:40","act":"Акт II · Сквозняк","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"},{"char":"vera","sprite":"neutral","pos":"left"}],"steps":[{"id":"t1","speaker":null,"text":"Шторм приходит в четыре сорок. Сначала просто шум, потом дом начинает гудеть, и все разговоры становятся короче."},{"id":"t2","speaker":null,"text":"Ким закрывает выход на щеколду и вешает поверх куртку — чтобы никто не вышел «на минуту»."},{"id":"t3","speaker":"vera","text":"— Дизель держит, но прокладка поёт. Если сорвёт — до утра не дотянем.","spriteOverride":"soft"},{"id":"t4","speaker":"kim","text":"— До утра никто не выходит. Ни на антенну, ни за снегом. — Он смотрит на тебя. — Врач, у тебя в аптечке всё, что нужно?","spriteOverride":"hard"},{"id":"t5","speaker":null,"text":"","choices":[{"text":"«Да, всё есть»","goto":"sc_a2_storm:c_yes"},{"text":"«Не хватает одного»","goto":"sc_a2_storm:c_no"}]},{"id":"c_yes","speaker":null,"text":"— Да, — говоришь ты. Ким кивает и больше не спрашивает.","goto":"sc_a2_storm:t6"},{"id":"c_no","speaker":null,"text":"— Не хватает обезболивающего, — говоришь ты. — Если будет травма, я смогу убрать боль, но не надолго. — Ким смотрит на тебя, как на человека, который сказал вслух то, о чём все молчали.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_storm:t6"},{"id":"t6","speaker":null,"text":"Аля сидит у стены, обняв наушники. Дан смотрит в стол. Гриша молчит и режет хлеб, хотя хлеб уже нарезан.","set":[{"var":"heat","op":"sub","value":1}]},{"id":"t7","speaker":null,"text":"Ты смотришь на часы. До полуночи ещё далеко — и это худшее, что можно сказать о вечере.","goto":"sc_a2_hub:t1"}]},{"id":"sc_a2_hub","name":"Кают-компания · 19:10","act":"Акт II · Сквозняк","bg":"assets/bg-hall.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"До полуночи остаётся пять часов. Пять часов — это слишком много для разговоров и слишком мало для работы."},{"id":"t2","speaker":null,"text":"Вера уходит в дизельную. Аля — в радиорубку, хотя связи нет. Ким садится у окна с фонарём. Дан остаётся в лаборатории."},{"id":"t3","speaker":null,"text":"Ты можешь успеть что-то одно. Выбирай."},{"id":"t4","speaker":null,"text":"","choices":[{"text":"Помочь Вере с дизелем","goto":"sc_a2_heat:t1"},{"text":"Посидеть с Алей в радиорубке","goto":"sc_a2_radio:t1"},{"text":"Поговорить с Кимом у окна","goto":"sc_a2_kim:t1"},{"text":"Перечитать журнал в медпункте","goto":"sc_a2_journal:t1"}]}]},{"id":"sc_a2_heat","name":"Дизельная · 19:30","act":"Акт II · Сквозняк","bg":"assets/bg-diesel.webp","weather":"none","cast":[{"char":"vera","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"Вера не удивляется. Она просто двигается, освобождая тебе место у кожуха."},{"id":"t2","speaker":"vera","text":"— Держи. И не говори ничего. — Пауза. — Ладно, говори. Под гул всё равно не слышно.","spriteOverride":"soft"},{"id":"t3","speaker":null,"text":"Вы меняете прокладку на самодельную: паронит, графит, терпение. Тепло возвращается на градус.","set":[{"var":"heat","op":"add","value":1}]},{"id":"t4","speaker":"vera","text":"— Завтра я скажу Киму, что это я. — Она не смотрит на тебя. — Если он спросит, откуда ты знал, — соври."},{"id":"t5","speaker":null,"text":"","choices":[{"text":"«Совру»","goto":"sc_a2_heat:c_lie"},{"text":"«Не буду врать»","goto":"sc_a2_heat:c_true"}]},{"id":"c_lie","speaker":null,"text":"— Совру, — говоришь ты. Она кивает, и почему-то от этого кивка становится холоднее.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_a2_heat:t6"},{"id":"c_true","speaker":null,"text":"— Не буду, — говоришь ты. — Я уже один раз промолчал за сегодня. — Вера смотрит на тебя и ничего не отвечает.","set":[{"var":"trust_vera","op":"add","value":1}],"goto":"sc_a2_heat:t6"},{"id":"t6","speaker":null,"text":"Наверху, в доме, загорается что-то красное — ты видишь отсвет на стене дизельной.","goto":"sc_a2_beacon:t1"}]},{"id":"sc_a2_radio","name":"Радиорубка · 19:35","act":"Акт II · Сквозняк","bg":"assets/bg-radio.webp","weather":"none","cast":[{"char":"alya","sprite":"neutral","pos":"center"}],"steps":[{"id":"t1","speaker":null,"text":"В радиорубке темно, только зелёный огонёк терминала. Аля сидит на полу, обняв колени."},{"id":"t2","speaker":"alya","text":"— Я боюсь не темноты. Я боюсь, что кто-то ответит.","spriteOverride":"scared"},{"id":"t3","speaker":null,"text":"","choices":[{"text":"«Тогда я посижу с тобой»","goto":"sc_a2_radio:c_stay"},{"text":"«Что ты имеешь в виду?»","goto":"sc_a2_radio:c_what"},{"text":"Включить приёмник","goto":"sc_a2_radio:c_on"}]},{"id":"c_stay","speaker":null,"text":"Ты садишься рядом на пол. Она кладёт голову тебе на плечо — просто, без объяснений.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_a2_radio:t4"},{"id":"c_what","speaker":null,"text":"— Если ответит не диспетчер, — говорит Аля. — Если ответит кто-то, кто знает, что мы здесь. — Она смотрит на терминал. — Я не хочу это слышать.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_a2_radio:t4"},{"id":"c_on","speaker":null,"text":"Ты включаешь приёмник. Шипение, ровное, как дыхание. Аля вздрагивает и зажимает уши.","set":[{"var":"trust_alya","op":"add","value":1}],"goto":"sc_a2_radio:t4"},{"id":"t4","speaker":null,"text":"Терминал мигает. Не сеанс: время не то. Просто помеха."},{"id":"t5","speaker":null,"text":"Ты сидишь в темноте, пока не становится ясно, что красный отсвет из коридора не кажется.","goto":"sc_a2_beacon:t1"}]},{"id":"sc_a2_kim","name":"Кают-компания · 19:30","act":"Акт II · Сквозняк","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"}],"steps":[{"id":"t1","speaker":null,"text":"Ким сидит у окна, глядя в чёрное стекло, где ничего не видно, кроме отражения лампы."},{"id":"t2","speaker":"kim","text":"— Я здесь двадцать шесть зим. Знаешь, что самое трудное? Не холод. Не связь. — Он поворачивается. — Знать, что кто-то из твоих людей сделал плохо, и всё равно считать его своим."},{"id":"t3","speaker":null,"text":"","choices":[{"text":"«О ком ты?»","goto":"sc_a2_kim:c_who"},{"text":"«Я понимаю»","goto":"sc_a2_kim:c_yes"},{"text":"«Расскажи про Славу»","goto":"sc_a2_kim:c_slava","if":"evidence \u003e= 4"}]},{"id":"c_who","speaker":null,"text":"— Обо всех, — говорит Ким. — По очереди. Так уж выходит.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_kim:t4"},{"id":"c_yes","speaker":null,"text":"— Понимаешь, — повторяет он. — Тогда поймёшь и остальное.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_kim:t4"},{"id":"c_slava","speaker":null,"text":"— Слава хотел отправить отчёт в обход, — говорит Ким, не глядя на тебя. — Я вышел за ним. Дальше — не сейчас.","set":[{"var":"trust_kim","op":"add","value":1},{"var":"evidence","op":"add","value":1}],"goto":"sc_a2_kim:t4"},{"id":"t4","speaker":"kim","text":"— Я тебе не отвечу. Пока. — Он снова смотрит в окно. — Но если ты что-то знаешь, скажи это раньше, чем узнаю я. Вторым будет хуже."},{"id":"t5","speaker":null,"text":"Ты киваешь и уходишь. В коридоре мигает красный — сначала ты думаешь, что это лампа.","goto":"sc_a2_beacon:t1"}]},{"id":"sc_a2_journal","name":"Медпункт · 19:40","act":"Акт II · Сквозняк","bg":"assets/bg-med.webp","weather":"none","cast":[],"steps":[{"id":"t1","speaker":null,"text":"Ты открываешь журнал на середине, там, где записи ещё почерком Славы."},{"id":"t2","speaker":null,"text":"Он писал подробно: пульс, давление, жалобы. А между строк — короткие пометки, которые не относятся к медицине."},{"id":"t3","speaker":null,"text":"«Д. снова не спит». «К. спрашивал про рейс». «Лёд у створа — 1,2, не 1,5»."},{"id":"t4","speaker":null,"text":"Ты пересчитываешь: одна и та же цифра повторяется четыре раза. 1,2. Как будто он хотел, чтобы её запомнили.","set":[{"var":"evidence","op":"add","value":1}]},{"id":"t5","speaker":null,"text":"Ты закрываешь журнал. В коридоре мигает красный, и ты идёшь на свет.","goto":"sc_a2_beacon:t1"}]},{"id":"sc_a2_beacon","name":"Кают-компания · 23:52","act":"Акт II · Сквозняк","bg":"assets/bg-hall.webp","weather":"none","cast":[{"char":"kim","sprite":"neutral","pos":"right"},{"char":"vera","sprite":"neutral","pos":"left"}],"steps":[{"id":"t1","speaker":null,"text":"В двадцать три пятьдесят две дом вздрагивает. Не от ветра: в коридоре, у щита, загорается красный.","set":[{"var":"beacon","op":"set","value":true}],"mood":"flash"},{"id":"t2","speaker":null,"text":"Аварийный маяк. Его включают руками, изнутри. И он уже передаёт сигнал — медленно, коротко, в пустоту."},{"id":"t3","speaker":"kim","text":"— Кто. Это. Сделал.","spriteOverride":"hard"},{"id":"t4","speaker":null,"text":"Вера смотрит на тебя. Аля — на дверь. Дан не поднимает глаз. Гриша держит кружку обеими руками."},{"id":"t5","speaker":null,"text":"","choices":[{"text":"Сказать, что видел свет на антенном поле","goto":"sc_a2_beacon:c_light","if":"saw_light"},{"text":"Спросить, что теперь будет","goto":"sc_a2_beacon:c_now"},{"text":"Молчать","goto":"sc_a2_beacon:c_silent"}]},{"id":"c_light","speaker":null,"text":"— Я видел свет на антенном поле, — говоришь ты. — В два часа ночи. — Вера не отводит глаз, и в комнате становится очень тихо.","set":[{"var":"evidence","op":"add","value":1}],"goto":"sc_a2_beacon:t6"},{"id":"c_now","speaker":null,"text":"— Что теперь будет? — спрашиваешь ты. Ким смотрит на красный огонь. — Теперь нас услышат. Рано или поздно.","set":[{"var":"trust_kim","op":"add","value":1}],"goto":"sc_a2_beacon:t6"},{"id":"c_silent","speaker":null,"text":"Ты молчишь. Красный свет делает лица плоскими, и ты вдруг понимаешь, что не знаешь, кому из них веришь.","goto":"sc_a2_beacon:t6"},{"id":"t6","speaker":"kim","text":"— Через сутки о нас узнают. — Он выключает маяк, но красный свет остаётся в комнате. — Значит, у нас есть сутки, чтобы решить, что мы скажем, когда спросят.","spriteOverride":"hard"},{"id":"t7","speaker":null,"text":"Ты смотришь на людей за столом и понимаешь: кто-то из них только что сделал выбор за всех."},{"id":"t8","speaker":null,"text":"За окном воет ветер. Где-то далеко, за льдом и водой, кто-то уже принял сигнал и записал координаты.\n\nЧерез сутки на станции появятся чужие голоса. Ты возвращаешься в медпункт и впервые за три недели запираешь дверь на щеколду.","end":true,"endTitle":"КОНЕЦ · Акт II"}]}],"baseUrl":"stories/tihaya/novels/ice-shift/","_builtin":"tihaya/novels/ice-shift"}]}]};
